```nix
imp = inputs.bootc-impurifier.lib.bootc-impurifier { inherit pkgs; };
image = imp.makeOfflineImage {
  base = myBootcBase; # A single-image OCI layout, already fetched or built.
  applications = [{ pkg = pkgs.hello; }];
  name = "my-host";
  tag = "v1";
};
```
